programs.haiku:
"""Layer 15 MLP down-projection, component 5248.

What it responds to: code-syntax tokens. It is strongly positive on the token that opens a
quoted string or a bracketed argument in code, such as ' "', '("', "('", '="', ' `', '["'.
It is moderately positive on code keywords (const, def, void, class, self, ...) and on code
markers (//, #, ->, ::, $, *, |). It is negative on tool-call JSON scaffolding and a few
generic words (assistant, name, arguments, execute, ...), and slightly negative elsewhere.
Only the newest token is read, so the prediction is a fixed mean per token class.

On training text the four classes explain about 6% of the variance. Most of the
activation varies with context that no token class captures.
"""

READS: tuple[str, ...] = ()

QUOTES = {'"', "'", "`", "“", '"""', '\\"'}
CODE_KEYWORDS = {"const", "let", "var", "void", "int", "def", "fn", "func", "function",
                 "class", "import", "mut", "String", "self", "public", "private", "struct"}
CODE_MARKERS = {"//", "#", "->", "::", ">", "$", "*", "|", "_", "--", "`", "##", "__", "=>"}
PROSE_NEGATIVE = {"assistant", "name", "arguments", "instance", "other", "execute",
                  "command", '":', "</tool_call>", "_replace", "root", "run", "day",
                  "else", "another", "second", "last", "total"}

# Mean activation of each class on training text.
CLASS_MEAN = {"open": 1.46, "keyword": 0.80, "marker": 0.60, "negative": -0.54, "other": -0.06}


def is_open_quote(token: str) -> bool:
    # A quote after a space (' "'), or right after an opening bracket or '=' ('("', '="').
    if token.startswith(" ") and token[1:] in QUOTES:
        return True
    return len(token) >= 2 and token[0] in "([{=" and token[1:] in QUOTES


def token_class(token: str) -> str:
    bare = token.strip()
    if is_open_quote(token):
        return "open"
    if bare in CODE_KEYWORDS:
        return "keyword"
    if bare in CODE_MARKERS:
        return "marker"
    if bare in PROSE_NEGATIVE:
        return "negative"
    return "other"


def step(carry, prefix, upstream):
    # Stateless: the prediction depends only on the newest token.
    return carry, CLASS_MEAN[token_class(prefix.token_strings[-1])]

"""Candidate v4: where the component goes negative, the text is setting up or
numbering a parallel list ("either ... or", "both ... and", "First, ... Second",
"two causes:", "(a) ... (b)", "1. ... 2."). Elsewhere it is small noise."""
import re

READS = ()

BASELINE = -0.09                      # its typical value on ordinary text
PAIR = {"either": -4.0, "both": -3.0, "neither": -1.5}
COUNT = {"two": -1.0, "three": -1.0, "four": -0.8, "several": -0.8,
         "following": -1.2, "follows": -1.2}
SENTENCE_BREAK = {"", ".", "?", "!", ":", "\n", "\n\n"}
LIST_MARK = re.compile(r"\d+|[a-z]")
BULLETS = {"-", "*", "•"}


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    tok = toks[-1]
    word = tok.strip().lower()
    prev = toks[-2] if len(toks) > 1 else ""
    if word in PAIR:
        return carry, PAIR[word]
    if word == "first":
        return carry, -3.5 if prev.strip() in SENTENCE_BREAK else -0.6
    if word in COUNT:
        return carry, COUNT[word]
    if ":\n" in tok:                  # a colon that ends a line introduces a list
        return carry, -0.8
    if LIST_MARK.fullmatch(word) and ("\n" in prev or prev.strip() in (":", "(")):
        return carry, -0.6            # "1", "(a", "i" starting a list item
    if tok.strip() in BULLETS and "\n" in prev:
        return carry, -0.6
    return carry, BASELINE

"""Negation detector: the component goes negative where the text denies or rules something out.

Its activation is mostly near zero. It goes negative on the words that deny or limit:
- "not", "no", "n't", "never", "none", "nothing", most strongly when they follow a
  copula or auxiliary ("is not", "are not", "was no", "does not"), which says that a
  property is absent;
- the same words more weakly after a modal or past auxiliary ("will not", "could not",
  "did not"), where the sign is weak or often positive;
- limiting words ("impossible", "difficult", "false", "null", "outside", "excluding");
- contrast words ("but", "however", "despite", "than"), more weakly.
Everything else predicts 0. The values are a least-squares fit of these classes on
sample text; the word lists are the concept, and the numbers are the scale.
"""

NEGATORS = {
    "not", "no", "n't", "'t", "’t", "never", "nothing", "none", "nor", "neither",
    "cannot", "non",
}
COPULA_AUX = {
    "is", "are", "was", "were", "am", "be", "does", "do", "has", "have", "must",
    "need", "'s", "’s",
}
MODAL_AUX = {
    "will", "can", "could", "would", "did", "may", "might", "should", "shall",
}
LIMIT_WORDS = {
    "impossible", "difficult", "invalid", "false", "null", "zero", "rare", "limited",
    "low", "outside", "excluding", "beyond", "unable",
}
CONTRAST = {"but", "however", "despite", "although", "though", "except", "than"}

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().lower()
    before = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if token in NEGATORS:
        if before in COPULA_AUX:
            return carry, -2.7
        if before in MODAL_AUX:
            return carry, -0.5
        return carry, -1.3
    if token in LIMIT_WORDS:
        return carry, -1.4
    if token in CONTRAST:
        return carry, -1.0
    return carry, 0.0

"""Indentation detector for code. The component goes negative on the whitespace that indents the
first token of a line of code, most strongly when the line above ends a block opener ('{' or ':'),
the point where a new statement of a block is about to start. Elsewhere it is near zero."""

READS = ()

BLOCK_OPENERS = {"{": -1.6, ":": -1.5}
OTHER_ENDINGS = {";": -0.9, ")": -0.5}
PLAIN_INDENT = -0.3
MID_LINE_INDENT = -0.6


def step(carry, prefix, upstream):
    # carry: (last non-blank character so far, whether a line has just started, document id)
    if carry is None or carry[2] != prefix.document_ids[-1]:
        last, at_line_start = "", True
    else:
        last, at_line_start = carry[0], carry[1]
    token = prefix.token_strings[-1]
    is_indent = token != "" and token.strip(" \t") == "" and "\n" not in token
    value = 0.0
    if is_indent and at_line_start:
        value = BLOCK_OPENERS.get(last) or OTHER_ENDINGS.get(last) or PLAIN_INDENT
    elif is_indent and len(token) >= 3:
        value = MID_LINE_INDENT
    if "\n" in token:
        at_line_start = True
    elif token.strip() != "":
        at_line_start = False
    stripped = token.rstrip(" \t\r\n\xa0")
    if stripped:
        last = stripped[-1]
    return (last, at_line_start, prefix.document_ids[-1]), value

"""Layer 15 MLP down-projection, component 5272 (a single rank-one piece).

The component reads the MLP hidden state and writes a small vector into the residual
stream. Its activation is mostly a diffuse, slightly positive signal (mean ~0.05, std
~0.35) with a few strong negative dips on words about dependence and variability:
"depend", "depends", "regardless", "something", "somehow", "arbitrary", "constant", "vary".

Honest caveat: this explains almost none of the variance (eval variance explained ~0.0004).
Most of the activation is a dense mix of many hidden units, not a word-level concept.
This program predicts the activation from the newest token's text alone:
  - the first token of each document gets 0 (the component is silent there);
  - a token containing "depend" gets -1.0;
  - a word from the variability list gets -0.5;
  - anything else gets the typical resting value, +0.05.
"""

READS = ()

DEPEND_STEM = "depend"
VARIABILITY_WORDS = frozenset({
    "regardless", "something", "somehow", "arbitrary", "constant", "vary", "without",
})
RESTING_VALUE = 0.05


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().lower()
    docs = prefix.document_ids
    starts_document = len(docs) < 2 or docs[-1] != docs[-2]
    if starts_document:
        value = 0.0
    elif DEPEND_STEM in token:
        value = -1.0
    elif token in VARIABILITY_WORDS:
        value = -0.5
    else:
        value = RESTING_VALUE
    return carry, float(value)

"""Layer 15 MLP neuron 5274 (down_proj component 5274), read as a word-level rule.

The component's input direction is almost entirely the MLP hidden unit 5274 itself, so its
activation is that unit's value. Its activation is diffuse and context-dependent: no word or
context explains most of it. A weak lexical tendency is captured here: it leans positive on
contrast and concession words ("but", "even", "though", "yet") and negative on necessity and
failure words ("need", "must", "required", "failed") and on "to" after "have/had".
"""

READS = ()

CONTRAST = {
    "but", "even", "though", "although", "yet", "however", "except", "only", "just",
    "actually", "already", "never", "simply", "always", "really", "enough",
}
NECESSITY = {"need", "needs", "must", "necessary", "require", "requires", "required"}
FAILURE = {"fail", "failed", "fails", "err", "problem", "problems", "issue", "issues", "wrong", "error"}
HAVE = {"have", "has", "had"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    same_doc = len(prefix.token_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = prefix.token_strings[-2].strip().lower() if same_doc else ""
    if word in CONTRAST:
        value = 0.3
    elif word in NECESSITY or word in FAILURE:
        value = -0.2
    elif word == "to" and before in HAVE:
        value = -0.5
    else:
        value = 0.0
    return carry, value

"""Layer 15 MLP down-projection, component 5310: an "aside opener" detector.

What it does, in plain terms:
- It is strongly positive on tokens that open an aside: an opening parenthesis or
  bracket such as " (" or " [". Those are the places where a writer starts a
  clarification, an abbreviation or alias ("computer assisted design (CAD)"),
  a defined term ("(hereinafter ...)") or a citation. How strong it is depends on
  the text before: it is high when the preceding ~48 tokens of the same document
  are plain words (prose), and low or negative when they are code, logs, test
  output or symbol-heavy text.
- It is strongly positive on citation lead-in words: "See", "see", "cite", "Id.",
  "Cf.", "hereinafter".
- It is negative at chat-template boundaries: the end of a turn (<|im_end|>, the
  end of a tool response or tool call) and the end of a thinking block (</think>).
- Everything else is 0.

The per-token value is an opener's base level plus a prose term, with the prose
term the share of the last 48 tokens (same document) that are alphabetic words.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

# Tokens that open a parenthesis, bracket or quotation-wrapped aside.
OPENERS = {" (", "（", " [", ".[", "[@", " (“", ' ("', "(", " (`", " ($", "(+"}
# Citation and cross-reference lead-ins (case-cited "See", "Id.", "Cf.", "hereinafter").
CITE_WORDS = {" See", "See", "cite", " Id", " cf", "fter"}
# Lower-case "see" is a weaker lead-in.
WEAK_CITE_WORDS = {" see", "see"}
# Chat-template boundaries: end of a thinking block, end of a turn or tool message.
THINK_END = {"</think>"}
TURN_END = {"<|im_end|>", "</tool_response>", "</tool_call>"}

WINDOW = 48  # tokens of the same document that count as context


def is_word(text: str) -> bool:
    """True for a plain alphabetic word token, such as ' the' or 'Berge'."""
    return text.strip().isalpha()


def step(carry, prefix, upstream: Mapping):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, [])  # a new document: forget the earlier text
    _, recent = carry

    if token in OPENERS:
        prose = sum(recent) / len(recent) if recent else 0.5
        value = -2.0 + 10.0 * prose
    elif token in CITE_WORDS:
        value = 8.0
    elif token in WEAK_CITE_WORDS:
        value = 3.0
    elif token in THINK_END:
        value = -12.0
    elif token in TURN_END:
        value = -6.0
    else:
        value = 0.0

    recent = (recent + [is_word(token)])[-WINDOW:]
    return (doc, recent), float(value)
